package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Turns completed downtime progress into Barbara review proposals without inventing rewards. */
public final class BarbaraDowntimeResolutionPlanner{
 private BarbaraDowntimeResolutionPlanner(){}
 public static JSONArray propose(JSONObject aggregate,int day){JSONArray out=new JSONArray();JSONObject portfolio=aggregate==null?null:aggregate.optJSONObject("downtime_portfolio");JSONObject projects=portfolio==null?null:portfolio.optJSONObject("projects");if(projects==null)return out;java.util.Iterator<String>it=projects.keys();while(it.hasNext()){String id=it.next();JSONObject p=projects.optJSONObject(id);if(p==null)continue;if(p.optBoolean("overdue",false)){JSONObject late=new JSONObject();try{late.put("type","downtime_overdue").put("subject",id).put("family",p.optString("family")).put("day",Math.max(1,day)).put("proposal","deadline_consequence_review").put("overdue_days",p.optInt("overdue_days",0)).put("requires_barbara_review",true).put("auto_mutation_allowed",false);}catch(Exception ignored){}out.put(late);}if(!"awaiting_authorized_resolution".equals(p.optString("status")))continue;JSONObject q=new JSONObject();try{q.put("type","downtime_resolution").put("subject",id).put("family",p.optString("family")).put("day",Math.max(1,day)).put("proposal","authorized_resolution_review").put("requires_barbara_review",true).put("auto_mutation_allowed",false).put("rule_id",p.optString("resolution_rule_id")).put("inputs",p.optJSONObject("resolution_inputs")==null?new JSONObject():p.optJSONObject("resolution_inputs"));String rule=p.optString("resolution_rule_id");if(!rule.isEmpty())q.put("procedure_gate",AuthorizedRuleProcedureEngine.gate(rule,q.optJSONObject("inputs")));}catch(Exception ignored){}out.put(q);}return out;}
}
